import itertools

# Helper functions
def time_to_minutes(t):
    # t like "9:15AM"
    h, m = int(t[:-5]), int(t[-5:-3])
    suffix = t[-2:]
    if suffix == 'PM' and h != 12:
        h += 12
    if suffix == 'AM' and h == 12:
        h = 0
    return h * 60 + m

def minutes_to_str(m):
    h = (m // 60) % 24
    minute = m % 60
    suffix = 'AM' if h < 12 else 'PM'
    h12 = h % 12
    if h12 == 0:
        h12 = 12
    return f"{h12}:{minute:02d}{suffix}"

# Travel times (minutes) as directed graph
travel = {
    'Financial District': {
        'Russian Hill': 10, 'Sunset District': 31, 'North Beach': 7,
        'The Castro': 23, 'Golden Gate Park': 23,
    },
    'Russian Hill': {
        'Financial District': 11, 'Sunset District': 23, 'North Beach': 5,
        'The Castro': 21, 'Golden Gate Park': 21,
    },
    'Sunset District': {
        'Financial District': 30, 'Russian Hill': 24, 'North Beach': 29,
        'The Castro': 17, 'Golden Gate Park': 11,
    },
    'North Beach': {
        'Financial District': 8, 'Russian Hill': 4, 'Sunset District': 27,
        'The Castro': 22, 'Golden Gate Park': 24,
    },
    'The Castro': {
        'Financial District': 20, 'Russian Hill': 18, 'Sunset District': 17,
        'North Beach': 20, 'Golden Gate Park': 11,
    },
    'Golden Gate Park': {
        'Financial District': 26, 'Russian Hill': 19, 'Sunset District': 10,
        'North Beach': 24, 'The Castro': 13,
    },
}

# Friends data
friends = [
    {
        'name': 'Ronald',
        'loc': 'Russian Hill',
        'win_start': time_to_minutes('1:45PM'),
        'win_end': time_to_minutes('5:15PM'),
        'duration': 105,
    },
    {
        'name': 'Patricia',
        'loc': 'Sunset District',
        'win_start': time_to_minutes('9:15AM'),
        'win_end': time_to_minutes('10:00PM'),
        'duration': 60,
    },
    {
        'name': 'Laura',
        'loc': 'North Beach',
        'win_start': time_to_minutes('12:30PM'),
        'win_end': time_to_minutes('12:45PM'),
        'duration': 15,
    },
    {
        'name': 'Emily',
        'loc': 'The Castro',
        'win_start': time_to_minutes('4:15PM'),
        'win_end': time_to_minutes('6:30PM'),
        'duration': 60,
    },
    {
        'name': 'Mary',
        'loc': 'Golden Gate Park',
        'win_start': time_to_minutes('3:00PM'),
        'win_end': time_to_minutes('4:30PM'),
        'duration': 60,
    },
]

START_LOC = 'Financial District'
START_TIME = time_to_minutes('9:00AM')

best_schedule = None
best_friends = []
best_end_time = None

# Explore all subsets (size from 5 down to 1)
for r in range(5, 0, -1):
    found = False
    for subset in itertools.combinations(friends, r):
        for order in itertools.permutations(subset):
            cur_loc = START_LOC
            cur_time = START_TIME
            steps = [f'You start at {START_LOC} at {minutes_to_str(START_TIME)}.']
            feasible = True
            for fr in order:
                travel_time = travel[cur_loc][fr['loc']]
                arrive = cur_time + travel_time
                steps.append(
                    f'You travel to {fr["loc"]} in {travel_time} minutes and arrive at {minutes_to_str(arrive)}.'
                )
                if arrive < fr['win_start']:
                    steps.append(f'You wait until {minutes_to_str(fr["win_start"])}.')
                    meet_start = fr['win_start']
                else:
                    meet_start = arrive
                meet_end = meet_start + fr['duration']
                if meet_end > fr['win_end']:
                    feasible = False
                    break
                steps.append(
                    f'You meet {fr["name"]} from {minutes_to_str(meet_start)} to {minutes_to_str(meet_end)}.'
                )
                cur_loc = fr['loc']
                cur_time = meet_end
            if feasible:
                # better schedule?
                if len(order) > len(best_friends) or (len(order) == len(best_friends) and (best_end_time is None or cur_time < best_end_time)):
                    best_friends = list(order)
                    best_schedule = steps
                    best_end_time = cur_time
                    found = True
        if found:
            break
    if found:
        break

# Output the itinerary list
print(best_schedule)
